describe('Login Page Mobile Responsiveness', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.viewport('iphone-x');
  });

  it('should display login form correctly on mobile viewport', () => {
    cy.get('[data-testid="login-container"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');

    cy.get('[data-testid="email-input"]').should('have.css', 'width').and('match', /\d+/);
    cy.get('[data-testid="password-input"]').should('have.css', 'width').and('match', /\d+/);

    cy.get('[data-testid="login-button"]').should('have.css', 'padding');
    cy.get('[data-testid="login-button"]').should('have.css', 'font-size');
  });

  it('should maintain proper spacing and layout on small mobile screens', () => {
    cy.viewport('iphone-se2');

    cy.get('[data-testid="login-container"]').should('be.visible');
    cy.get('[data-testid="login-title"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');

    cy.get('[data-testid="email-input"]').invoke('outerHeight').should('be.gte', 44);
    cy.get('[data-testid="password-input"]').invoke('outerHeight').should('be.gte', 44);
    cy.get('[data-testid="login-button"]').invoke('outerHeight').should('be.gte', 44);
  });

  it('should display form elements without horizontal scrolling on mobile', () => {
    cy.viewport('iphone-x');

    cy.get('[data-testid="login-container"]').then(($container) => {
      const containerWidth = $container.outerWidth();
      cy.window().then((win) => {
        expect(containerWidth).to.be.lte(win.innerWidth);
      });
    });

    cy.get('[data-testid="email-input"]').should('not.have.css', 'overflow', 'auto');
    cy.get('[data-testid="password-input"]').should('not.have.css', 'overflow', 'auto');
  });

  it('should handle touch interactions on mobile devices', () => {
    cy.viewport('iphone-x');

    cy.get('[data-testid="email-input"]').should('be.visible').click();
    cy.get('[data-testid="email-input"]').type('test@example.com');
    cy.get('[data-testid="email-input"]').should('have.value', 'test@example.com');

    cy.get('[data-testid="password-input"]').should('be.visible').click();
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="password-input"]').should('have.value', 'password123');

    cy.get('[data-testid="login-button"]').should('be.visible').click();
  });

  it('should display error messages properly on mobile without layout breaking', () => {
    cy.viewport('iphone-x');

    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').invoke('outerWidth').then((errorWidth) => {
      cy.window().then((win) => {
        expect(errorWidth).to.be.lte(win.innerWidth);
      });
    });
  });
});
